import Foundation

public enum Engine: String, CaseIterable, Sendable {
  case parakeet
  case whisper
  case apple

  public var name: String {
    switch self {
    case .parakeet: "Parakeet"
    case .whisper: "Whisper"
    case .apple: "Apple"
    }
  }
}

/// One file of a model, pinned to the bytes the manifest script saw on Hugging Face.
struct ModelFile: Sendable, Hashable {
  let path: String
  let size: Int64
  let sha256: String
}

/// Every file a model needs, at one Hugging Face commit. Generated by
/// `scripts/models/pin-manifests.py` into ModelManifests.swift.
public struct ModelManifest: Sendable, Hashable {
  let repository: String
  let revision: String
  /// Prepended to each file's path on disk. Parakeet keeps the folder FluidAudio loads from.
  let localPrefix: String
  let files: [ModelFile]

  public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

  func remoteURL(for file: ModelFile) -> URL {
    guard let base = URL(string: "https://huggingface.co/\(repository)/resolve/\(revision)/") else {
      preconditionFailure("The manifest for \(repository) has an invalid repository name")
    }
    return base.appending(path: file.path)
  }

  func localPath(for file: ModelFile) -> String { localPrefix + file.path }
}

/// The models a user can install. The raw value is the stored active-model preference and names
/// the install path, so changing one makes an installed copy unknown.
public enum ModelID: String, CaseIterable, Sendable, Identifiable {
  case parakeetV3 = "parakeet-tdt-0.6b-v3-coreml"
  case parakeetUltra = "parakeet-ultra-coreml"
  case whisperTurbo = "large-v3-turbo"
  case appleDictation = "apple-dictation-transcriber"
  case appleSpeech = "apple-speech-transcriber"

  public static let preferred = ModelID.parakeetV3

  public var id: Self { self }

  /// The one switch from identity to provider. Every other per-model fact derives from it.
  public var provider: ModelProvider {
    switch self {
    case .parakeetV3: .hosted(HostedModel(id: self, engine: .parakeet(.v3), pinned: .parakeetV3))
    case .parakeetUltra: .hosted(HostedModel(id: self, engine: .parakeet(.ultra), pinned: .parakeetUltra))
    case .whisperTurbo: .hosted(HostedModel(id: self, engine: .whisper, pinned: .whisperTurbo))
    case .appleDictation: .system(.dictation)
    case .appleSpeech: .system(.speech)
    }
  }

  public var engine: Engine {
    switch provider {
    case .hosted(let model): model.engine.engine
    case .system: .apple
    }
  }

  public var name: String {
    switch self {
    case .parakeetV3: "Parakeet v3"
    case .parakeetUltra: "Parakeet Ultra"
    case .whisperTurbo: "Whisper Turbo"
    case .appleDictation: "Dictation"
    case .appleSpeech: "Speech"
    }
  }

  public var summary: String {
    switch self {
    case .parakeetV3:
      "NVIDIA's multilingual model. Detects the language on its own and adds punctuation and capitals."
    case .parakeetUltra:
      "Moondream's retraining of Parakeet v3. Same 25 languages, with fewer mistakes."
    case .whisperTurbo:
      "OpenAI's Whisper large-v3, pruned for speed. Much faster, with a minor drop in quality."
    case .appleDictation:
      "Apple's dictation model, the one macOS keyboard dictation uses. Transcribes one language you choose."
    case .appleSpeech:
      "Apple's newer general transcription model, with full punctuation. Transcribes one language you choose."
    }
  }
}

/// Where a model's files come from.
public enum ModelProvider: Sendable, Hashable {
  case hosted(HostedModel)
  /// Speech assets macOS downloads and manages, one set per language.
  case system(SystemModel)
}

/// A model whose files OpenVocally fetches, verifies and keeps in the local-models folder. Built
/// only by `ModelID.provider`, so its engine and manifest always match its id.
public struct HostedModel: Sendable, Hashable, Identifiable {
  public let id: ModelID
  public let engine: HostedEngine
  let pinned: ModelManifest

  fileprivate init(id: ModelID, engine: HostedEngine, pinned: ModelManifest) {
    self.id = id
    self.engine = engine
    self.pinned = pinned
  }

  var rawValue: String { id.rawValue }

  /// Where the model lives under the local-models folder: a folder per Parakeet model, a
  /// `ggml-*.bin` file per Whisper model.
  var installPath: String {
    switch engine {
    case .parakeet: "\(engine.engine.rawValue)/\(rawValue)"
    case .whisper: "\(engine.engine.rawValue)/ggml-\(rawValue).bin"
    }
  }

  /// Whisper is one file, installed by moving that file. The others install as a folder.
  var isSingleFile: Bool {
    switch engine {
    case .parakeet: false
    case .whisper: true
    }
  }
}

/// How a hosted model loads.
public enum HostedEngine: Sendable, Hashable {
  case parakeet(ParakeetVariant)
  case whisper

  var engine: Engine {
    switch self {
    case .parakeet: .parakeet
    case .whisper: .whisper
    }
  }

  /// The languages the model card states.
  public var languageCount: Int {
    switch self {
    case .parakeet: 25
    case .whisper: 99
    }
  }
}

public enum ParakeetVariant: Sendable, Hashable {
  case v3
  case ultra
}

extension ModelID {
  static var hosted: [HostedModel] {
    allCases.compactMap { model in
      switch model.provider {
      case .hosted(let hosted): hosted
      case .system: nil
      }
    }
  }
}
